(function(){
'use strict';
const DATA=window.MANDATE_DATA.politics,MAPS=window.MANDATE_DATA,E=window.Engine,app=document.getElementById('app'),modal=document.getElementById('modal');
const KEY='mandate-2026-career-v2';let state=null,step=1,country='AU',jurisdiction='AU',countrySearch='',districtSearch='',regionFilter='',mapZoom=1,mapFocus=null;
let draft={name:'Alex Morgan',age:35,background:'Community organiser',year:2026,party:'',home:'',platform:'Housing',custom:false,customName:'New Horizon Party',customShort:'NHP',customColour:'#9475b6',sandboxSeats:100,sandboxTerm:4};
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=x=>Math.round(Number(x)||0).toLocaleString(),flag=code=>code==='GB'?'UK':code,initials=n=>String(n).split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase();
const paths={parliament:'M3 9l9-6 9 6M4 10h16M6 12v7m6-7v7m6-7v7M3 21h18',hq:'M3 10l9-7 9 7v10H3V10Zm6 10v-7h6v7',map:'m3 6 6-3 6 3 6-3v15l-6 3-6-3-6 3V6Zm6-3v15m6-12v15',policy:'M6 3h9l4 4v14H6V3Zm9 0v5h4M9 12h7m-7 4h7',finance:'M3 6h18v14H3V6Zm0 4h18M6 15h4M6 3h12',profile:'M12 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8Zm-8 9v-2a8 8 0 0 1 16 0v2',sources:'M5 4h14v16H5V4Zm4 4h6m-6 4h6m-6 4h4',door:'M5 21V3h14v18M2 21h20M15 12h1',rally:'m3 11 17-7v16L3 13v-2Zm4 3 2 7h4l-2-6',debate:'M3 4h18v13H10l-5 4v-4H3V4Zm5 6h1m3 0h1m3 0h1',recruit:'M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8ZM2 21v-3a7 7 0 0 1 14 0v3m3-13v8m-4-4h8',fundraise:'M4 7h16v14H4V7Zm4-4h8v4M8 13h8m-8 4h4',research:'M10 17a7 7 0 1 0 0-14 7 7 0 0 0 0 14Zm5-2 6 6',services:'M3 9h18v12H3V9Zm6 0V4h6v5M9 15h6m-3-3v6',media:'M3 4h18v16H3V4Zm4 3h5v5H7V7Zm8 0h3m-3 4h3M7 16h11',scrutiny:'M12 3 3 7v6c0 4 4 7 9 9 5-2 9-5 9-9V7l-9-4Zm-4 9 3 3 5-6',organise:'M3 4h6v6H3V4Zm12 0h6v6h-6V4ZM9 16h6v6H9v-6Zm-3-6v3h12v-3m-6 3v3',arrow:'M5 12h14m-5-5 5 5-5 5',save:'M4 3h14l3 3v15H3V3h1Zm3 0v6h9V3M7 21v-8h10v8',load:'M12 3v12m-4-4 4 4 4-4M3 17v4h18v-4',plus:'M12 4v16M4 12h16',check:'m4 12 5 5L20 6',close:'m5 5 14 14M19 5 5 19',calendar:'M4 5h16v16H4V5Zm0 5h16M8 2v6m8-6v6',settings:'M4 7h16M4 17h16M8 3v8m8 2v8'};
const icon=(name,cls='')=>`<svg class="${esc(cls)}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.parliament}"/></svg>`;
const button=(text,act,cls='button',extra='')=>`<button class="${cls}" data-action="${act}" ${extra}>${text}</button>`;
function getProfile(code=state?.profile||jurisdiction){return DATA.countries[code]||DATA.regions.find(x=>x.code===code)}
function save(){try{if(state)localStorage.setItem(KEY,JSON.stringify(state))}catch{toast('Autosave is unavailable in this browser. Export a save to keep your career.')}}
function toast(message){const t=document.getElementById('toast');t.textContent=message;t.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('visible'),3500)}
function load(){try{const s=JSON.parse(localStorage.getItem(KEY));if(E.validSave(s,DATA))state=s}catch{}}
load();
function brand(){return '<a class="brand" href="#" data-action="home"><img src="assets/mark.svg" alt=""><div><div class="brand-name">MANDATE</div><div class="brand-sub">A political life</div></div></a>'}
const systemName=p=>({'fptp':'First past the post','av':'Full preferential','av-optional':'Optional preferential','mmp-nz':'Mixed-member proportional','mmp-de':'Mixed-member proportional','list-pr':'Party-list proportional','stv':'Single transferable vote','ams':'Additional member system','parallel':'Parallel mixed system','us-pres':'Electoral College','pres-two':'Two-round presidency','governor':'Statewide plurality','governor-two':'Statewide majority/runoff','governor-av':'Ranked-choice executive','approximate':'Simplified sandbox'})[p.mode]||'Institutional profile';
function flatcoords(g){if(!g?.coordinates)return [];const points=[];function walk(c){if(typeof c[0]==='number')points.push(c);else c.forEach(walk)}walk(g.coordinates);return points}
function svgMap(p,{world=false,setup=false,height=330}={}){
 const key=world?'world':p.map||'world',data=MAPS[key]||MAPS.world,features=data.features.filter(f=>f.properties.name!=='Antarctica'),w=740,h=height;
 let points=features.flatMap(f=>flatcoords(f.geometry)),bounds=world||key==='world'?[-180,-60,180,85]:[Math.min(...points.map(x=>x[0])),Math.min(...points.map(x=>x[1])),Math.max(...points.map(x=>x[0])),Math.max(...points.map(x=>x[1]))];
 if(mapFocus&&key!=='world'){
  const f=features.find(x=>x.properties.name===mapFocus);if(f){const a=flatcoords(f.geometry),pad=1;bounds=[Math.min(...a.map(x=>x[0]))-pad,Math.min(...a.map(x=>x[1]))-pad,Math.max(...a.map(x=>x[0]))+pad,Math.max(...a.map(x=>x[1]))+pad]}
 }
 const scale=Math.min((w-35)/(bounds[2]-bounds[0]),(h-30)/(bounds[3]-bounds[1]))*mapZoom,xOffset=(w-(bounds[2]-bounds[0])*scale)/2,yOffset=(h-(bounds[3]-bounds[1])*scale)/2;
 const project=c=>[(c[0]-bounds[0])*scale+xOffset,h-((c[1]-bounds[1])*scale+yOffset)];
 function ring(c){return c.map((a,i)=>{const x=project(a);return(i?'L':'M')+x[0].toFixed(1)+','+x[1].toFixed(1)}).join('')+'Z'}
 function path(g){return g.type==='Polygon'?g.coordinates.map(ring).join(''):g.type==='MultiPolygon'?g.coordinates.flatMap(x=>x.map(ring)).join(''):''}
 const byName=new Map((state?.results?.rows||[]).map(x=>[x.name,x])),byCode=new Map((state?.results?.rows||[]).map(x=>[x.region,x])),base=new Map(p.districts.map(x=>[x.name,x]));
 let pathsHTML=features.map(f=>{const a=f.properties,n=a.name,code=a.code;let fill='#d8e1df',action=setup&&world?'map-country':'map-seat',id=setup&&world?code:n,selected=setup&&world?code===country:n===state?.home;
  if(setup&&world)fill=code===country?'#aa8abd':'#dbe3df';
  else if(state&&key!=='world'){const r=key==='us-states'?byCode.get(a.region):byName.get(n);const win=r?state.parties[r.winner]:state.parties.find(x=>x.name===base.get(n)?.winner);fill=win?.colour||'#c4d1cc';if(n===state.home)fill=state.parties[state.player].colour}
  else if(key==='world')fill=code===(p.country||p.code)?'#9d80b4':'#dbe3df';
  const known=setup&&world?!!DATA.countries[code]:key!=='world';return `<path d="${path(f.geometry)}" fill="${fill}" class="map-feature ${selected?'selected':''}" ${known?`data-action="${action}" data-id="${esc(id)}" tabindex="0" role="button" aria-label="${esc(n)}"`:''}><title>${esc(n)}</title></path>`}).join('');
 return `<div class="map-zone"><svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${world?'World countries':esc(p.name)+' map'}"><rect width="${w}" height="${h}" fill="#f1f5f3"/>${pathsHTML}</svg><div class="map-tools">${button('+','zoom-in','','aria-label="Zoom in"')}${button('−','zoom-out','','aria-label="Zoom out"')}${button('↺','map-reset','','aria-label="Reset map"')}</div><div class="map-caption">${key==='world'?'Natural Earth · generalised outlines':key==='us-states'?'Natural Earth · state outlines':'ABS ASGS 2025 · simplified mesh-block boundaries'}</div></div>`
}
function countryList(){let list=Object.values(DATA.countries);if(countrySearch)list=list.filter(p=>p.name.toLowerCase().includes(countrySearch.toLowerCase())||p.code.toLowerCase()===countrySearch.toLowerCase());else{const featured=['AU','US','GB','CA','NZ','DE','IN','FR','JP','BR','ZA'];list.sort((a,b)=>(featured.includes(a.code)?featured.indexOf(a.code):1000)-(featured.includes(b.code)?featured.indexOf(b.code):1000)||a.name.localeCompare(b.name))}
 return list.map(p=>`<button class="country-button ${p.code===country?'selected':''}" data-action="country" data-id="${p.code}"><span class="flag">${flag(p.code)}</span><span class="country-label"><b>${esc(p.name)}</b><small>${p.mode==='approximate'?'Institutional profile · simplified':esc(p.coverage)}</small></span><span class="arrow">›</span></button>`).join('')||'<div class="empty">No country matches that search.</div>'
}
function setup(){const p=getProfile(),c=DATA.countries[country],regions=DATA.regions.filter(x=>x.country===country),limited=p.restricted||p.mode==='approximate';
 app.innerHTML=`<header class="setup-header">${brand()}<div class="row"><span class="tag">2026 DATA EDITION</span>${button(icon('sources')+' About & sources','about','button compact')}${state?button('Resume career','resume','button primary compact'):''}</div></header><main class="setup-main"><div class="setup-title"><div><div class="eyebrow">${step===1?'Every career starts somewhere':step===2?'Make your mark':'Ready for the campaign trail'}</div><h1>${step===1?'The world is your electorate.':step===2?'A new political life.':'Your path to power.'}</h1><p>${step===1?'Choose a country, explore its political system, and decide where your career begins.':step===2?'Build your politician, join a real party or start your own, and choose your seat.':'Review the rules and data coverage before beginning your campaign.'}</p></div><div class="tag purple">${Object.keys(DATA.countries).length} countries · ${DATA.regions.length} regional profiles</div></div><div class="steps">${[1,2,3].map((n,i)=>`<div class="step ${step===n?'active':''}"><b>${n}</b>${['Choose your arena','Your politician','Review & begin'][i]}</div>`).join('')}</div>${step===1?`
 <div class="setup-grid"><section class="card country-picker"><div class="card-head"><h3>Choose a country</h3><span class="tag small">197</span></div><input class="search" id="country-search" aria-label="Search countries" placeholder="Search country or code…" value="${esc(countrySearch)}"><div class="country-list" id="country-list">${countryList()}</div><div class="divider"></div><div class="field"><label for="jurisdiction">Election level</label><select id="jurisdiction"><option value="${country}">National · ${esc(c.chamber)}</option>${regions.map(r=>`<option value="${r.code}" ${r.code===jurisdiction?'selected':''}>${esc(r.name)} · ${esc(r.office)}</option>`).join('')}</select><small>${regions.length?regions.length+' regional elections available in this country.':'Regional elections are not yet individually researched for this country.'}</small></div></section>
 <section class="card map-panel"><div class="map-head"><div class="row between"><span class="tag ${limited?'gold':'green'}">${limited?'LIMITED / SANDBOX':'SOURCED PROFILE'}</span><span class="small muted">${flag(country)} ${esc(c.name)}</span></div><h2>${esc(p.name)}</h2><p class="small muted">${esc(systemName(p))} · ${esc(p.office)}</p></div>${svgMap(p,{world:true,setup:true,height:315})}<div class="map-stats"><div><span class="eyebrow">Chamber size</span><b>${p.seats?fmt(p.seats):'Custom'}</b><small>${p.mode==='governor'||p.mode==='governor-two'?'Executive office':'Statutory seats'}</small></div><div><span class="eyebrow">Office term model</span><b>${p.executiveTerm||p.term||'Custom'}${p.term?' years':''}</b><small>Each term turn = 3 months</small></div><div><span class="eyebrow">Named districts</span><b>${fmt(p.districtCount||0)}</b><small>${p.realDistricts?'Official names bundled':'Not individually verified'}</small></div></div><div class="map-footer"><div class="notice ${limited?'':'info'}"><strong>${esc(p.coverage)}</strong>${esc(p.rules)}</div><div class="source-note">${esc(p.partyStatus)} Snapshot: 5 October 2026.</div><div class="setup-bottom"><small class="muted">Facts set the stage.<br>Your choices write the story.</small>${button('Create your politician '+icon('arrow'),'next','button primary')}</div></div></section></div>`:step===2?politicianForm(p):review(p)}<footer class="setup-footer"><span>Researched institutions and dated party data. Campaign outcomes and events are fictional.</span><span>MANDATE © 2026 · <a href="https://github.com/ashtonleearcher98-ship-it/Election-sim" target="_blank" rel="noopener">Source code</a> · ${button('Import career','import','button ghost compact')}</span></footer></main>`;
 if(step===2){const options=document.getElementById('party');if(!draft.party&&options)draft.party=options.value;const h=document.getElementById('home');if(!draft.home&&h)draft.home=h.value}
}
function politicianForm(p){const districts=p.districts.length?p.districts:[{name:'Simulated constituency 1',region:'Unverified district names'}],parties=p.parties.filter(x=>!['Speaker','No Party Affiliation','Other 2025 affiliations'].includes(x.name));if(!parties.length)draft.custom=true;
 return `<div class="setup-grid"><section class="stack"><div class="card"><div class="eyebrow">Your arena</div><h2 class="serif" style="margin:12px 0">${flag(country)} ${esc(p.name)}</h2><div class="small muted">${esc(p.office)} · ${esc(systemName(p))}</div><div class="divider"></div><div class="small muted" style="line-height:1.7">${esc(p.partyStatus)}</div>${p.notes.length?`<div class="source-note">${p.notes.map(esc).join('<br><br>')}</div>`:''}</div><div class="notice"><strong>2026 data snapshot</strong>Choosing another start year creates an alternate timeline using the same 2026 institutions and party roster. Historical party lists are not reconstructed.</div></section><section class="card"><div class="profile-preview"><div class="avatar" id="preview-initials">${esc(initials(draft.name))}</div><div><h3 id="preview-name">${esc(draft.name)}</h3><small>${esc(p.office)} candidate · ${esc(p.name)}</small></div></div><div class="form-grid"><div class="field"><label for="name">Politician’s name</label><input id="name" maxlength="60" value="${esc(draft.name)}" autocomplete="off"></div><div class="field"><label for="age">Age</label><input id="age" type="number" min="18" max="90" value="${draft.age}"><small>Candidacy age and citizenship rules are abstracted.</small></div><div class="field"><label for="background">Background</label><select id="background">${['Community organiser','Local councillor','Economist','Journalist','Public servant','Business owner'].map(x=>`<option ${x===draft.background?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label for="year">Start year</label><input id="year" type="number" min="1900" max="2200" value="${draft.year}"></div><div class="field full"><label>Your party</label><div class="choice-row">${button('Join an existing party','join-party','choice '+(!draft.custom?'selected':''),parties.length?'':'disabled')}${button('Start a new party','new-party','choice '+(draft.custom?'selected':''))}</div></div>${draft.custom?`<div class="field"><label for="customName">New party name</label><input id="customName" maxlength="70" value="${esc(draft.customName)}"></div><div class="field"><label for="customShort">Abbreviation</label><input id="customShort" maxlength="8" value="${esc(draft.customShort)}"></div><div class="field"><label for="customColour">Party colour</label><input id="customColour" type="color" value="${draft.customColour}" style="height:42px"><small>Party registration and nomination are abstracted.</small></div>`:`<div class="field full"><label for="party">Choose a party / parliamentary group</label><select id="party">${parties.map(x=>`<option value="${esc(x.name)}" ${x.name===draft.party?'selected':''}>${esc(x.name)}${x.seats?' · '+x.seats+' baseline seats':''}</option>`).join('')}</select><small>${esc(p.partyStatus)}</small></div>`}<div class="field full"><label for="seat-search">Find your seat, electorate or home state</label><input id="seat-search" placeholder="Filter ${districts.length} districts…" aria-label="Filter districts"><select id="home" aria-label="Home constituency">${districts.map(d=>`<option value="${esc(d.name)}" ${draft.home===d.name?'selected':''}>${esc(d.name)}${d.region?' · '+esc(d.region):''}</option>`).join('')}</select><small>${p.realDistricts?'Official district names are bundled. Local voting probabilities are simulated.':'Actual district names are not bundled. This is a labelled simulated constituency slot.'}${p.electionKind==='executive'?' Your home seat is a career biography; the executive election is separate.':''}</small></div><div class="field full"><label for="platform">Campaign priority</label><select id="platform">${['Housing','Health','Economy','Education','Climate','Integrity'].map(x=>`<option ${x===draft.platform?'selected':''}>${x}</option>`).join('')}</select><small>Your priorities are your choices; they do not represent an official party manifesto.</small></div>${p.restricted||!p.term?`<div class="field"><label for="sandboxSeats">Sandbox chamber size</label><input id="sandboxSeats" type="number" min="1" max="1000" value="${draft.sandboxSeats}"></div><div class="field"><label for="sandboxTerm">Sandbox term (years)</label><input id="sandboxTerm" type="number" min="1" max="10" value="${draft.sandboxTerm}"></div>`:''}</div><div class="setup-bottom">${button('← Back','back','button')}${button('Review your career '+icon('arrow'),'next','button primary')}</div></section></div>`
}
function readDraft(){for(const key of ['name','age','year','background','party','home','platform','customName','customShort','customColour','sandboxSeats','sandboxTerm']){const el=document.getElementById(key);if(el)draft[key]=['age','year','sandboxSeats','sandboxTerm'].includes(key)?Number(el.value):el.value}draft.name=draft.name.trim()||'Alex Morgan';draft.age=E.clamp(draft.age,18,90);draft.year=E.clamp(draft.year,1900,2200)}
function review(p){return `<div class="two-columns"><div class="card"><div class="eyebrow">Your candidate</div><div class="profile-preview" style="margin-top:20px"><div class="avatar">${esc(initials(draft.name))}</div><div><h3>${esc(draft.name)}</h3><small>${esc(draft.background)} · age ${draft.age}</small></div></div><div class="chart-row"><span>Party</span><span>${esc(draft.custom?draft.customName:draft.party)}</span></div><div class="chart-row"><span>Home constituency</span><span>${esc(draft.home)}</span></div><div class="chart-row"><span>Office sought</span><span>${esc(p.office)}</span></div><div class="chart-row"><span>Campaign priority</span><span>${esc(draft.platform)}</span></div><div class="chart-row"><span>Start year</span><span>${draft.year}${draft.year!==2026?' · alternate timeline':''}</span></div><div class="divider"></div><div class="notice info"><strong>Your first campaign</strong>Eight campaign weeks, three actions each week. Winning begins a term; losing begins an opposition career. Every government or opposition turn advances three months.</div><div class="setup-bottom">${button('← Edit politician','back','button')}${button('Begin campaign '+icon('arrow'),'launch','button primary')}</div></div><div class="card"><div class="eyebrow">Know the rules</div><h2 class="serif" style="margin:15px 0">${esc(p.name)}</h2><p class="small muted">${esc(p.rules)}</p><div class="notice ${p.restricted?'':'info'}"><strong>${esc(p.coverage)}</strong>${esc(p.partyStatus)}</div><div class="source-note">${p.notes.map(x=>'<p>'+esc(x)+'</p>').join('')}</div><div class="divider"></div><h3>What is simulated?</h3><p class="small muted">Polls, approval, preference ballots, coalition willingness, events, the economy, campaign funds and policy effects are game mechanics. They are not current polling or predictions. Electoral mechanics are simplified where noted; facts retain their source dates.</p>${button('View source register','profile-sources','button compact')}</div></div>`}
function phaseName(){if(state.personalSeatLoss)return 'Outside Parliament';return {campaign:'Campaign',government:'In government',opposition:'In opposition',negotiation:'Government formation'}[state.phase]}
function dateName(){const y=Math.floor(state.year),q=Math.floor((state.year-y)*4)+1;return `Q${q} ${y}`}
const nav=[['hq','hq','Headquarters'],['parliament','parliament','Parliament'],['map','map','Electoral map'],['policies','policy','Policy & manifesto'],['finance','finance','Finances'],['profile','profile','Your career'],['sources','sources','Sources & rules']];
function workspace(){const p=getProfile(),party=state.parties[state.player],tab=state.tab||'hq';
 app.innerHTML=`<div class="workspace"><aside class="sidebar">${brand()}<div class="side-section">YOUR POLITICAL LIFE</div><nav aria-label="Career navigation">${nav.map(([id,i,n])=>button(icon(i)+n,'tab','nav-item '+(tab===id?'active':''),`data-id="${id}"`)).join('')}</nav><div class="sidebar-bottom"><div class="side-career"><div class="avatar">${esc(initials(state.name))}</div><div><strong>${esc(state.name)}</strong><small>${esc(p.name)}</small></div></div><div class="side-save">${button(icon('save')+' Export','export','button')}${button(icon('load')+' Import','import','button')}</div>${button(icon('plus')+' New career','new','nav-item','style="margin-top:10px;font-size:10px"')}</div></aside><div class="main-area"><header class="topbar"><div class="breadcrumb"><span>${flag(p.country||p.code)}</span><strong>${esc(p.name)}</strong><span>/</span><span>${esc(nav.find(x=>x[0]===tab)?.[2]||'Headquarters')}</span></div><div class="topbar-right"><div class="date-box">${dateName()}<small>${state.phase==='campaign'?'CAMPAIGN WEEK '+state.week:'TERM '+state.termNumber+' · QUARTER '+state.quarter}</small></div><span class="status-pill">${phaseName()}</span></div></header><main class="page">${state.scenario?`<div class="notice" style="margin-bottom:18px"><strong>Alternate-history / simplified sandbox</strong>${p.restricted?'Competitive elections do not reflect this jurisdiction’s present institutional situation. ':''}${p.mode==='approximate'?'Electoral allocation and government formation use generic sandbox rules. ':''}Source facts remain dated; campaign outcomes are fictional.</div>`:''}${state.startYear!==2026?`<div class="notice info" style="margin-bottom:18px">Alternate timeline: ${state.startYear} start using the 2026 data snapshot, not historical parties or boundaries.</div>`:''}${tab==='hq'?headquarters(p):tab==='parliament'?parliament(p):tab==='map'?electoralMap(p):tab==='policies'?policies(p):tab==='finance'?finance(p):tab==='profile'?career(p):sourcesPage(p)}<div class="bottom-note"><span>2026 source snapshot · Your campaign, results and events are fictional.<br>Detailed rules vary by profile. Open Sources & rules for coverage and dates.</span><span>Autosaved locally · ${button('Export save','export','button ghost compact')}</span></div></main></div><nav class="career-mobile-nav" aria-label="Mobile career navigation">${nav.filter(x=>['hq','parliament','map','policies','profile','sources'].includes(x[0])).map(([id,i,n])=>button(icon(i)+({'policies':'Policy','parliament':'Seats','hq':'HQ','map':'Map','profile':'Career','sources':'Sources'})[id],'tab',tab===id?'active':'',`data-id="${id}"`)).join('')}</nav></div>${state.event?eventModal():''}`;
}
function title(eyebrow,heading,description,controls=''){return `<div class="page-title"><div><div class="eyebrow">${esc(eyebrow)}</div><h1>${esc(heading)}</h1><p>${esc(description)}</p></div>${controls?'<div class="row">'+controls+'</div>':''}</div>`}
function metric(label,value,suffix,foot,bar){return `<div class="card metric"><div class="metric-label">${esc(label)}<span>↗</span></div><div class="metric-value">${esc(value)}<span>${esc(suffix)}</span></div><div class="metric-foot">${esc(foot)}</div>${bar!==undefined?`<div class="metric-bar"><i style="width:${E.clamp(bar)}%"></i></div>`:`<svg class="spark" viewBox="0 0 90 30"><path d="M1 25 13 22 25 24 37 15 48 18 60 9 72 12 88 3"/></svg>`}</div>`}
function nextButton(){return button(state.retired?'Career complete':state.phase==='campaign'?state.week===8?'Election night '+icon('arrow'):'Next campaign week '+icon('arrow'):state.phase==='negotiation'?'Take opposition benches':'Advance 3 months '+icon('arrow'),'advance','button primary',state.event||state.retired?'disabled':'')}
function headquarters(p){const party=state.parties[state.player],poll=state.poll[state.player],phase=state.phase,counts=state.results?.counts||state.parties.map(x=>x.seats),own=counts[state.player]||0;
 const focus=state.personalSeatLoss?['Win back your constituency.','Your party governs under a replacement leader. Rebuild your local standing and return to Parliament.']:phase==='campaign'?['The campaign is yours to shape.','Earn trust in your home seat and take your message to the country. Rivals campaign between weeks.']:phase==='government'?['A mandate is only the beginning.','Deliver your programme, respond to events, and maintain public confidence through the term.']:phase==='negotiation'?['The balance of power is in play.','Seek confidence support from other parties or prepare to lead the opposition.']:['Build the case for an alternative.','Hold the government to account, serve your community, and prepare for the next election.'];
 const actionIDs=phase==='campaign'?['door','rally','debate','recruit','fundraise','research']:['services','media','scrutiny','organise','fundraise','research'];
 return title('YOUR CAMPAIGN, YOUR COUNTRY',phase==='campaign'?'Campaign headquarters':phase==='government'?'The work of government':phase==='negotiation'?'Form a government':state.personalSeatLoss?'Rebuild your local career':'Opposition headquarters',phase==='campaign'?`Week ${state.week} of 8 · ${state.name}, candidate for ${p.office}.`:`${state.name} · ${state.wonHome?'Seated party leader':'Party leader outside the chamber'} · ${p.office} career.`,nextButton())+`
 <div class="metric-grid" style="margin-bottom:20px">${metric('Party support',poll.toFixed(1),'%','Simulated support, not a real poll',poll)}${metric(phase==='campaign'?'Local standing':'Leader approval',Math.round(phase==='campaign'?state.local:state.approval),'%','Simulated public satisfaction',phase==='campaign'?state.local:state.approval)}${metric('Party campaign funds',fmt(state.partyFunds),'pts','Party funds · separate from public budget')}${metric('Actions available',state.actions,'/ 3',phase==='campaign'?'This campaign week':'This three-month turn',state.actions/3*100)}</div>
 <div class="dashboard-grid"><div class="main-stack"><div class="card focus-card"><div class="watermark">${icon('parliament')}</div><div class="focus-content"><div class="eyebrow">${phase==='campaign'?'ON THE CAMPAIGN TRAIL':phase==='government'?'YOUR GOVERNING PROGRAMME':'YOUR NEXT MOVE'}</div><h2>${focus[0]}</h2><p>${focus[1]}</p><div class="row">${button(phase==='government'?'Open policy programme':'Explore electoral map',phase==='government'?'policy-shortcut':'map-shortcut','button compact')}${button('View election rules','sources-shortcut','button ghost compact')}</div></div></div>
 ${phase==='negotiation'?negotiation():`<section class="card"><div class="card-head"><div><span class="eyebrow">${phase==='campaign'?'CAMPAIGN OPERATIONS':'POLITICAL OPERATIONS'}</span><h3>Choose your next action</h3></div><span class="tag purple">${state.actions} actions left</span></div><div class="action-grid">${actionIDs.map(id=>actionCard(id)).join('')}</div></section>`}
 ${state.results?`<div class="card"><div class="card-head"><h3>Last election</h3>${button('Full results →','parliament-shortcut','button ghost compact')}</div><div class="result-banner ${phase==='opposition'?'opposition':''}"><strong>${phase==='government'?'You formed government':phase==='negotiation'?'A parliament to negotiate':state.personalSeatLoss?'Your party won; you lost your seat':'Your party continues in opposition'}</strong>${p.electionKind==='executive'?(p.mode==='us-pres'?fmt(state.results.electors[state.player])+' Electoral College votes · 270 required':state.results.votes[state.player].toFixed(1)+'% simulated final vote'):`${own} seats for ${esc(party.name)} · ${state.results.majority} for a majority.`} ${state.wonHome?'You hold a seat or executive office.':state.personalSeatLoss?'Your party governs under a replacement leader. You rebuild your local career outside Parliament.':'Your local career continues outside office.'}</div></div>`:''}
 <section class="card map-panel"><div class="map-head"><div class="row between"><h3>${p.map==='world'?'Your political arena':'The electoral landscape'}</h3>${button('Open map →','map-shortcut','button ghost compact')}</div></div>${svgMap(p,{height:250})}<div class="map-footer" style="padding-top:14px"><span class="small muted">${esc(p.realDistricts?p.districtCount+' named districts in this profile.':'Real world outline; individual electorate names are not bundled.')}</span></div></section></div>
 <aside class="dashboard-side"><div class="stack"><section class="card side-card candidate-card"><div class="row between"><div class="eyebrow">YOUR CANDIDATE</div><span class="dot" style="background:${party.colour}"></span></div><div class="row" style="margin-top:18px"><div class="avatar">${esc(initials(state.name))}</div><div><h3 class="candidate-name" style="margin:0 0 7px">${esc(state.name)}</h3><span class="tag">${esc(party.short||'PARTY')}</span></div></div><p class="seat-name" style="margin-top:17px">${esc(state.home)}</p><div class="candidate-details"><div><small>BACKGROUND</small><strong>${esc(state.background)}</strong></div><div><small>PRIORITY</small><strong>${esc(state.platform)}</strong></div><div><small>PUBLIC TRUST</small><strong>${Math.round(state.trust)}%</strong></div><div><small>LOCAL STANDING</small><strong>${Math.round(state.local)}%</strong></div></div></section>
 <section class="card side-card"><div class="card-head"><h3>Party standings</h3><span class="eyebrow">SIMULATED</span></div>${partyStandings(5)}<div class="source-note">Opening strength uses a dated seat baseline where available. Support is a game estimate.</div></section>
 <section class="card side-card"><h3>${phase==='campaign'?'The campaign calendar':'The term calendar'}</h3><div class="campaign-status"><span>${phase==='campaign'?'Week '+state.week+' of 8':'Quarter '+state.quarter+' of '+state.termYears*4}</span><span>${phase==='campaign'?'Election ahead':'3-month turns'}</span></div><div class="timeline">${Array.from({length:phase==='campaign'?8:Math.round(state.termYears*4)},(_,i)=>`<i class="${i<(phase==='campaign'?state.week-1:state.quarter)?'complete':i===(phase==='campaign'?state.week-1:state.quarter)?'current':''}"></i>`).join('')}</div><div class="source-note">${phase==='campaign'?'Election night follows campaign week eight.':'Term duration follows this profile’s rules. Approval affects your next campaign.'}</div></section>
 <section class="card side-card"><h3>From your political diary</h3>${state.log.slice(0,3).map(x=>`<div class="log-item"><small>${esc(x.at)}</small><p>${esc(x.message)}</p></div>`).join('')}</section></div></aside></div>`
}
function actionCard(id){const a=E.actions[id],blocked=state.actions<=0||state.partyFunds<a.cost||state.event||state.retired;return `<button class="action-card" data-action="act" data-id="${id}" ${blocked?'disabled':''}><span class="action-icon">${icon(id)}</span><strong>${a.name}</strong><p>${{door:'Build trust in your chosen constituency.',rally:'Reach voters beyond your home seat.',debate:'Make your case under the spotlight.',recruit:'Strengthen your local organisation.',fundraise:'Keep your campaign financially viable.',research:'Listen before making your next move.',services:'Solve local issues and earn trust.',media:'Explain your priorities to the public.',scrutiny:'Question decisions and demand answers.',organise:'Prepare your party for the next contest.'}[id]}</p><div class="action-bottom"><span>${a.cost<0?'+'+(-a.cost)+' funds':a.cost+' funds'}</span><span>1 action ↗</span></div></button>`}
function partyStandings(limit){const order=state.parties.map((p,i)=>({p,i,v:state.poll[i]})).sort((a,b)=>b.v-a.v);return `<div class="party-list">${order.slice(0,limit).map(({p,i,v})=>`<div><div class="party-line"><span class="dot" style="background:${p.colour}"></span><span class="party-name" title="${esc(p.name)}">${esc(p.name)}${i===state.player?' · You':''}</span><b>${v.toFixed(1)}%</b></div><div class="party-track"><span style="width:${v}%;background:${p.colour}"></span></div></div>`).join('')}</div>`}
function negotiation(){const r=state.results,backing=state.coalition.reduce((a,i)=>a+r.counts[i],0);return `<section class="card"><div class="card-head"><div><span class="eyebrow">CONFIDENCE & SUPPLY</span><h3>${backing} supporting seats / ${r.majority} required</h3></div><span class="tag gold">Hung parliament</span></div><p class="small muted">Negotiation willingness is fictional, not an assessment of real party ideology. Agreements cost public trust as you compromise.</p><div class="negotiation-grid">${state.parties.map((p,i)=>i!==state.player&&r.counts[i]>0?`<div class="negotiation-option"><h3><span class="dot" style="background:${p.colour}"></span> ${esc(p.name)}</h3><p>${r.counts[i]} seats · ${state.coalition.includes(i)?'Agreement secured':'Potential confidence support'}</p>${button(state.coalition.includes(i)?'Supporting your government':'Seek an agreement','coalition','button compact',`data-id="${i}" ${state.coalition.includes(i)?'disabled':''}`)}</div>`:'').join('')}</div><div class="divider"></div>${button('Take the opposition benches','opposition','button')}<div class="source-note">This approximates government formation. Minority governments, head-of-state discretion and special power-sharing rules are not fully modelled.</div></section>`}
function chamber(counts,parties){const total=counts.reduce((a,x)=>a+x,0);if(!total)return '<div class="empty">No sourced opening seat allocation.<br>Your first election will populate the chamber.</div>';const rings=Math.max(3,Math.round(Math.sqrt(total)/2.2)),points=[],weights=Array.from({length:rings},(_,i)=>1+i*.55),sum=weights.reduce((a,x)=>a+x,0);let left=total;
 for(let r=0;r<rings;r++){const n=r===rings-1?left:Math.round(total*weights[r]/sum);left-=n;const radius=72+r*104/Math.max(1,rings-1);for(let j=0;j<n;j++){const angle=Math.PI-(j+.5)/n*Math.PI;points.push({x:220+radius*Math.cos(angle),y:198-radius*Math.sin(angle),angle})}}
 points.sort((a,b)=>b.angle-a.angle);let k=0,svg='';const dotRadius=Math.min(5.4,Math.max(1.15,Math.sqrt(950/total)));
 counts.forEach((n,i)=>{for(let j=0;j<n;j++){const q=points[k++];if(q)svg+=`<circle cx="${q.x.toFixed(2)}" cy="${q.y.toFixed(2)}" r="${dotRadius.toFixed(2)}" fill="${parties[i]?.colour||'#d6dedb'}"><title>${esc(parties[i]?.name||'Unallocated')} · one seat</title></circle>`}});
 return `<svg class="chamber-svg" viewBox="0 0 440 230" role="img" aria-label="${total} parliamentary seats by party">${svg}</svg><div class="chamber-summary"><b>${fmt(total)}</b><small>SEATS IN THIS CHAMBER</small></div>`
}
function parliament(p){const real=!!state.results;let parties=[...state.parties],counts=real?[...state.results.counts]:state.parties.map(x=>x.seats);if(!real&&p.seats>counts.reduce((a,x)=>a+x,0)){parties.push({name:'Unallocated / vacancy / omitted group',short:'—',colour:'#d5dfdc'});counts.push(p.seats-counts.reduce((a,x)=>a+x,0))}
 const total=counts.reduce((a,x)=>a+x,0),majority=Math.floor(total/2)+1;return title('THE BALANCE OF POWER',p.seats===1?'The executive contest':'Parliament & election results',real?'Results from your simulated election. Real-world baseline data remains separately dated.':p.partyStatus,button(icon('sources')+' Sources','sources-shortcut','button'))+`${p.seats===1?`<div class="card"><h2 class="serif">${esc(p.name)} · Governor</h2><p class="small muted">The gubernatorial office is a separate election from the state legislature. A one-person executive office is not a parliamentary chamber.</p>${partyStandings(state.parties.length)}</div>`:`<div class="two-columns"><section class="card"><div class="card-head"><div><span class="eyebrow">${real?'YOUR SIMULATED RESULT':'DATED OPENING SEAT BASELINE'}</span><h3>${esc(p.chamber)}</h3></div><span class="tag purple">${majority} for a majority</span></div>${chamber(counts,parties)}<div class="seat-legend">${parties.filter((x,i)=>counts[i]>0).slice(0,8).map((x)=>`<span><i class="dot" style="background:${x.colour}"></i>${esc(x.short)}</span>`).join('')}</div><div class="source-note">${real?'One dot represents one simulated seat.':'One dot represents one baseline seat. '+esc(p.partyStatus)}${p.code==='US'?' The House is separate from the Presidency; simulated House allocation is an abstract legislative-support model.':''}</div></section><section class="card"><div class="card-head"><h3>Seat distribution</h3><span class="eyebrow">${real?'SIMULATED':'BASELINE'}</span></div>${counts.map((n,i)=>({n,p:parties[i],i})).sort((a,b)=>b.n-a.n).filter(x=>x.n).map(({n,p:x,i})=>`<div class="chart-row"><div class="row"><span class="dot" style="background:${x.colour}"></span><span title="${esc(x.name)}">${esc(x.short||x.name.slice(0,15))}${i===state.player?' · You':''}</span></div><div class="bar"><i style="width:${n/Math.max(1,total)*100}%;background:${x.colour}"></i></div><b>${n}</b></div>`).join('')}<div class="divider"></div><div class="small muted">${real?(state.phase==='government'?'Government support: '+state.coalition.reduce((a,i)=>a+counts[i],0)+' seats.':state.personalSeatLoss?'Your party has a majority; a replacement leader governs.':state.phase==='negotiation'?'Government formation is in progress.':'You are out of executive office; incumbent government formation is abstracted.'):'Baseline date: '+esc(p.partyDate||p.election||'not verified')}<br>Government formation requires confidence; the game uses majority support.</div></section></div>`}
 ${p.mode==='us-pres'?electoralCollege():''}${state.results?.runoff?runoffChart():''}<section class="card" style="margin-top:20px"><div class="card-head"><h3>${p.electionKind==='executive'?'Executive election detail':'District results'}</h3><span class="tag">${real?'Simulated result':'Source baseline'}</span></div>${districtTable(p)}</section>`}
function electoralCollege(){const r=state.results;return `<section class="card" style="margin-top:20px"><div class="card-head"><div><span class="eyebrow">PRESIDENTIAL CONTEST</span><h3>The Electoral College</h3></div><span class="tag purple">270 of 538 to win</span></div>${r?`<div class="electoral-progress">${r.electors.map((n,i)=>n?`<span style="width:${n/538*100}%;background:${state.parties[i].colour}" title="${esc(state.parties[i].name)}: ${n}"></span>`:'').join('')}</div><div class="seat-legend">${r.electors.map((n,i)=>n?`<span><i class="dot" style="background:${state.parties[i].colour}"></i>${esc(state.parties[i].short)} ${n}</span>`:'').join('')}</div>`:'<p class="small muted">State allocations total 538. Maine and Nebraska split two statewide electors and district electors. Your first election will populate this result.</p>'}<div class="source-note">The national popular vote does not directly choose the winner. Starting state polling is simulated, not a current poll. No majority leads to a contingent election, which is not fully modelled.</div></section>`}
function runoffChart(){const r=state.results.runoff;return `<section class="card" style="margin-top:20px"><div class="card-head"><h3>Two-round executive result</h3><span class="tag">Simulated</span></div>${r.qualifiers.map(i=>`<div class="chart-row"><span>${esc(state.parties[i].short)}</span><span class="muted">First round ${r.first[i].toFixed(1)}% → Final ${r.final[i].toFixed(1)}%</span></div>`).join('')}<div class="source-note">Preference transfers in the runoff are simulated.</div></section>`}
function districtRows(p){if(state.results)return state.results.rows;return p.mode==='us-pres'?p.presidentialStates:p.districts}
function districtTable(p){const rows=districtRows(p).filter(d=>d.name.toLowerCase().includes(districtSearch.toLowerCase())&&(!regionFilter||d.region===regionFilter)),regions=[...new Set(districtRows(p).map(d=>d.region))].filter(Boolean).sort();
 return `<div class="table-controls"><input id="district-search" class="search" value="${esc(districtSearch)}" placeholder="Search districts…" aria-label="Search district results"><select id="region-filter" class="search" aria-label="Filter region"><option value="">All regions</option>${regions.map(n=>`<option ${n===regionFilter?'selected':''}>${esc(n)}</option>`).join('')}</select><span class="small muted">${rows.length} districts</span></div><div class="district-table" id="district-table-body">${tableBody(p,rows)}</div>`}
function tableBody(p,rows){if(!rows.length)return '<div class="empty">No matching named districts. This profile has limited district coverage.</div>';return `<table class="data-table"><thead><tr><th>District / electorate</th><th>Region</th><th>${state.results?'Winner / largest group':'Baseline party / allocation'}</th><th>${state.results?'Your simulated vote':'Source detail'}</th><th>Action</th></tr></thead><tbody>${rows.slice(0,800).map(d=>{const party=state.results?state.parties[d.winner]:state.parties.find(x=>x.name===d.winner);return `<tr class="${d.name===state.home?'home':''}"><td>${esc(d.name)}${d.name===state.home?' <span class="tag purple">Home</span>':''}</td><td>${esc(d.region||'—')}</td><td>${party?`<span class="dot" style="background:${party.colour}"></span> `:''}${esc(party?.name||d.winner|| (d.electors?d.electors+' electors':'No vote baseline'))}${d.magnitude?' · '+d.magnitude+' seats':''}</td><td>${state.results?(d.votes?.[state.player]||0).toFixed(1)+'%':d.margin!=null?'TCP / half-margin '+d.margin.toFixed(1)+' pts':d.member?esc(d.member):d.date?esc(d.date):'Rules/names only'}</td><td>${button(d.name===state.target?'Targeted':'Target','target','button compact',`data-id="${esc(d.name)}"`)}</td></tr>`}).join('')}</tbody></table>${rows.length>800?'<div class="source-note">Showing the first 800 matches. Search to narrow the list.</div>':''}`}
function electoralMap(p){return title('WHERE THE CONTEST IS WON','The electoral landscape','Explore the source geography and target the seats where your organisation can make a difference.',button('Reset view','map-reset','button'))+`<div class="card map-panel"><div class="map-head"><div class="row between"><div><h3>${esc(p.name)}</h3><p class="small muted">${p.map==='world'?'Country outline — electorate polygons are not bundled for this profile.':p.code==='US'?'State shapes for the presidential contest. Congressional district polygons are not bundled.':'Bundled ABS district boundaries; source vintage and approximations are listed below.'}</p></div><span class="tag purple">${state.results?'Simulated winners':'Source geography'}</span></div></div>${svgMap(p,{height:420})}<div class="map-footer" style="padding-top:15px"><div class="row between wrap"><span class="small muted">Campaign target: <strong>${esc(state.target||state.home)}</strong></span><span class="small muted">${p.map==='world'?'Named districts remain searchable below.':'Click a district to inspect its campaign role.'}</span></div></div></div><section class="card" style="margin-top:20px"><div class="card-head"><h3>Find a district</h3><span class="tag">${p.realDistricts?'Official names':'Limited names'}</span></div>${districtTable(p)}<div class="source-note">A district table is not a geographic map. ABS state geometry is 2025 vintage. Queensland uses boundaries applicable in 2026, not its future 2028 redistribution. Maps are simplified for gameplay and do not determine your actual electoral enrolment.</div></section>`}
function policies(p){return title('YOUR IDEAS, YOUR RESPONSIBILITY',state.phase==='government'?'The policy programme':'Your manifesto',state.phase==='government'?'Choose legislation, manage the fiscal cost, and earn support through delivery.':'Prepare your alternative programme. Opposition proposals build support without spending the public budget.',nextButton())+`<div class="notice info" style="margin-bottom:20px"><strong>Simulated policy effects</strong>These are player-chosen policies and abstract gameplay outcomes, not official real-party manifestos. ${state.phase==='campaign'?'Your campaign priority is '+esc(state.platform)+'. Policy proposals become available after the election.':state.phase==='opposition'?'You can advocate, scrutinise and publish alternatives; only government can enact spending.':'Public budget: '+fmt(state.budget)+' points. Party campaign funds are separate.'}</div><div class="policy-grid">${E.policies.map(x=>{const passed=state.enacted.includes(x.id),proposed=state.pendingBills.includes(x.id);let label=passed?'Enacted this term':state.phase==='government'?'Introduce legislation':proposed?'Alternative published':state.phase==='opposition'?'Publish alternative':'Campaign proposal';let disabled=state.phase==='government'?(passed||state.actions<=0||state.budget<x.cost):state.phase==='opposition'?(proposed||state.actions<=0||state.partyFunds<3):true;return `<section class="card policy-card"><span class="eyebrow">${x.area}</span><h3>${x.name}</h3><p>${x.description}</p><div class="policy-cost"><span>Budget <b>${x.cost<0?'+':''}${-x.cost}</b></span><span>Approval <b>${x.approval>0?'+':''}${x.approval}</b></span></div>${button(label,'policy','button '+(passed?'':'primary'),`data-id="${x.id}" ${disabled||state.event?'disabled':''}`)}</section>`}).join('')}</div>`}
function finance(p){return title('A SUSTAINABLE POLITICAL LIFE','Campaign & public finances','Keep your party solvent. Government spending uses a separate public budget; all values are abstract game points.',nextButton())+`<div class="two-columns"><section class="card"><div class="card-head"><h3>Party organisation</h3><span class="tag purple">Campaign funds</span></div><div class="metric-value">${fmt(state.partyFunds)} <span>points</span></div><p class="small muted" style="margin-top:15px">Pay for campaigning, organising and opposition advocacy. Transparent fundraising replenishes the party’s resources.</p><div class="financial-stats"><div class="financial-stat"><small>Turn income</small><b>${state.phase==='campaign'?3:8}</b></div><div class="financial-stat"><small>Fundraising action</small><b>+14</b></div></div><div class="divider"></div>${button('Fundraise transparently','act','button primary',`data-id="fundraise" ${state.actions<=0||state.event?'disabled':''}`)}</section><section class="card"><div class="card-head"><h3>Public budget & economy</h3><span class="tag">${state.phase==='government'?'You manage this':'Incumbent government'}</span></div><div class="financial-stats"><div class="financial-stat"><small>Public fiscal reserve</small><b>${fmt(state.budget)}</b></div><div class="financial-stat"><small>Economic health index</small><b>${Math.round(state.economy)}</b></div></div><p class="small muted" style="margin-top:19px">These are fictional indices, not real GDP, revenue or debt. Policies and simulated shocks affect the fiscal reserve and economic health.</p><div class="notice info">${state.phase==='opposition'?'Opposition actions cannot change the public budget or economic index directly.':'Policy spending is charged to the public reserve, not party campaign funds.'}</div></section></div>`}
function career(p){return title('THE PERSON BEHIND THE PARTY','Your political life','Track your career, constituency work, election record and public confidence.',button('Export career','export','button'))+`<div class="two-columns"><section class="card"><div class="profile-preview"><div class="avatar">${esc(initials(state.name))}</div><div><h3>${esc(state.name)}</h3><small>${esc(state.background)} · began age ${state.age} in ${state.startYear}</small></div></div><div class="chart-row"><span>Party</span><span>${esc(state.parties[state.player].name)}</span></div><div class="chart-row"><span>Home</span><span>${esc(state.home)}</span></div><div class="chart-row"><span>Office sought</span><span>${esc(state.office)}</span></div><div class="chart-row"><span>Terms won</span><span>${state.termsWon}</span></div><div class="chart-row"><span>Local standing</span><span>${Math.round(state.local)}%</span></div><div class="chart-row"><span>Public trust</span><span>${Math.round(state.trust)}%</span></div><div class="divider"></div>${approvalChart()}<div class="source-note">Leader approval is simulated. A party leader may sit through an abstracted list route in proportional profiles even if the home district is not won.</div></section><section class="card"><div class="card-head"><h3>Your election record</h3><span class="tag">${state.history.length} contests</span></div>${state.history.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Year</th><th>Vote</th><th>Seats</th><th>Outcome</th></tr></thead><tbody>${state.history.map(x=>`<tr><td>${Math.floor(x.year)}</td><td>${x.vote.toFixed(1)}%</td><td>${x.seats}</td><td>${esc(x.phase)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Your first election is still ahead.<br>Complete eight campaign weeks to begin your record.</div>'}<div class="divider"></div><h3>Political diary</h3>${state.log.slice(0,8).map(x=>`<div class="log-item"><small>${esc(x.at)}</small><p>${esc(x.message)}</p></div>`).join('')}</section></div>`}
function approvalChart(){const values=state.approvalHistory.length>1?state.approvalHistory:[state.approval,state.approval],path=values.map((v,i)=>(i?'L':'M')+(i/(values.length-1)*400).toFixed(1)+','+(120-v*.9).toFixed(1)).join('');return `<div class="row between"><span class="eyebrow">APPROVAL THROUGH THIS TERM</span><strong class="small">${Math.round(state.approval)}%</strong></div><svg viewBox="0 0 400 135" style="width:100%;margin-top:14px" role="img" aria-label="Approval trend through the current simulated term"><path d="M0 75H400" stroke="#e7e2ec" stroke-dasharray="4 5"/><path d="${path}" stroke="#9375b5" stroke-width="2.5" fill="none"/><text x="0" y="133" fill="#90a0a8" font-size="9">Start of term</text><text x="360" y="133" fill="#90a0a8" font-size="9">Now</text></svg>`}
function sourcesPage(p){const sources=DATA.sources.filter(x=>p.sources.includes(x.id));return title('FACTS SET THE STAGE','Sources, rules & coverage','Know which facts are sourced, which date they refer to, and which parts are simplified gameplay.',button('About Mandate','about','button'))+`<div class="two-columns" style="margin-bottom:20px"><section class="card"><span class="eyebrow">${esc(p.name)}</span><h2 class="serif" style="margin-top:14px">${esc(systemName(p))}</h2><p class="small muted">${esc(p.rules)}</p><div class="notice info"><strong>${esc(p.coverage)}</strong>${esc(p.partyStatus)}</div><div class="source-note">${p.notes.map(x=>'<p>'+esc(x)+'</p>').join('')}</div></section><section class="card"><span class="eyebrow">THE SIMULATION CONTRACT</span><h2 class="serif" style="margin-top:14px">Read the date, know the difference.</h2><p class="small muted">A party’s last election result is not necessarily its current parliamentary strength. A current caucus is not a full list of registered parties. Each profile identifies which kind of list it uses.</p><p class="small muted">Preferences are generated or transferred by a fictional model. Coalitions, polls, economic indices, actions and policy effects are invented game mechanics. Candidate eligibility, primaries, reserved seats, regional compensation, minority government, power sharing and cohabitation are abstracted where noted.</p><div class="notice">197 countries are selectable. Full real electorates, current party registries and state elections are not yet comprehensively verified worldwide. Limited profiles use clearly labelled sandbox data.</div></section></div><div class="source-grid">${sources.map(sourceCard).join('')||'<div class="card empty">No verified country-specific source pack is bundled. This jurisdiction is sandbox only.</div>'}</div><div class="card" style="margin-top:20px"><h3>Research and attribution</h3><p class="small muted">The dedicated official-source research phase ran 03:49:08–04:14:13 UTC on 5 October 2026 (25 minutes 5 seconds), before rebuilding. Additional data checks continued during implementation. Source facts are frozen to the 2026 snapshot; live updates are not automatic.</p><p class="small muted">IPU-derived global data is CC BY-NC-SA 4.0. ABS geometry is CC BY 4.0. Natural Earth maps are public domain. The code has a separate MIT licence. See the repository’s data attribution and research ledger.</p><a class="small" href="RESEARCH.md" target="_blank" rel="noopener">Read research ledger →</a> · <a class="small" href="DATA-LICENSES.md" target="_blank" rel="noopener">Data licences →</a></div>`}
function sourceCard(x){return `<section class="card source-card"><span class="tag">${esc(x.date)}</span><h3>${esc(x.title)}</h3><p>${esc(x.scope)}</p><a class="source-url" href="${esc(x.url)}" target="_blank" rel="noopener">Open official source ↗</a><div class="source-note">${esc(x.license)}</div></section>`}
function eventModal(){const ev=state.event;return `<div class="event-overlay" role="dialog" aria-modal="true" aria-labelledby="event-title"><section class="card event-card"><span class="tag purple">${state.phase==='opposition'?'OPPOSITION RESPONSE':'GOVERNMENT DECISION'} · SIMULATED EVENT</span><h2 id="event-title">${esc(ev.title)}</h2><p>${esc(ev.text)}</p>${state.phase==='opposition'?'<p class="small muted">You can advocate a response; the incumbent controls spending.</p>':''}${ev.choices.map((c,i)=>button(`<span>${esc(c.name)}</span><small>${state.phase==='opposition'?Math.max(0,Math.ceil(-c.budget/3))+' party funds':(c.budget>=0?'+':'')+c.budget+' public budget'}</small>`,'resolve','event-option',`data-id="${i}" ${state.phase==='government'&&state.budget+c.budget<0||state.phase==='opposition'&&state.partyFunds<Math.max(0,Math.ceil(-c.budget/3))?'disabled':''}`)).join('')}<div class="source-note">This event and its consequences are fictional.</div></section></div>`}
function render(){state?workspace():setup()}
function showModal(html){modal.innerHTML=button(icon('close'),'close-modal','button ghost compact modal-close','aria-label="Close dialog"')+html;modal.showModal()}
function about(){showModal('<div class="eyebrow">MANDATE · 2026 EDITION</div><h2 style="margin-top:15px">A political life, shaped by you.</h2><p>Choose a country, join a party or build your own, campaign for office and manage a term. Each government or opposition turn advances three months. Elections distinguish parliamentary confidence from directly elected executive office.</p><p>The game combines dated institutional facts with fictional gameplay. Detailed profiles cover selected jurisdictions; worldwide institutional profiles have explicit gaps. It does not claim exact current electorates and party registrations in every country.</p><p>Research began 03:49:08 UTC and completed its first phase at 04:14:13 UTC on 5 October 2026: 25 minutes 5 seconds, before the rebuild.</p><p><a href="RESEARCH.md" target="_blank" rel="noopener">Research ledger</a> · <a href="DATA-LICENSES.md" target="_blank" rel="noopener">Data attribution</a> · <a href="https://github.com/ashtonleearcher98-ship-it/Election-sim" target="_blank" rel="noopener">GitHub repository</a></p>')}
function exportSave(){if(!state)return;const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='mandate-'+Math.floor(state.year)+'-career.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Career exported.')}
function launch(){readDraft();const p=getProfile();if(draft.custom&&!draft.customName.trim()){toast('Give your new party a name.');return}if(draft.custom&&p.parties.some(x=>x.name.toLowerCase()===draft.customName.trim().toLowerCase())){toast('Choose a distinct name for your new party.');return}
 state=E.create(p,{name:draft.name,age:draft.age,year:draft.year,background:draft.background,party:draft.custom?draft.customName:draft.party,home:draft.home,platform:draft.platform,customParty:draft.custom?{name:draft.customName.trim(),short:draft.customShort.trim(),colour:draft.customColour}:null,...(p.restricted||!p.term?{sandboxSeats:E.clamp(draft.sandboxSeats,1,1000),sandboxTerm:E.clamp(draft.sandboxTerm,1,10)}:{})});districtSearch='';regionFilter='';mapZoom=1;mapFocus=null;save();render();window.scrollTo(0,0)}
app.addEventListener('click',handleClick);modal.addEventListener('click',handleClick);
app.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('.map-feature[data-action]')){e.preventDefault();handleClick(e)}});
function handleClick(e){const el=e.target.closest('[data-action]');if(!el)return;e.preventDefault();const a=el.dataset.action,id=el.dataset.id;
 if(a==='home'){if(state){state.tab='hq';render()}else{step=1;setup()}return}
 if(a==='about'){about();return}if(a==='close-modal'){modal.close();return}if(a==='import'){document.getElementById('import').click();return}if(a==='export'){exportSave();return}
 if(a==='country'||a==='map-country'){if(!DATA.countries[id])return;country=id;jurisdiction=id;draft.party='';draft.home='';draft.custom=!getProfile().parties.length;mapZoom=1;mapFocus=null;setup();return}
 if(a==='next'){if(step===2)readDraft();step=Math.min(3,step+1);setup();window.scrollTo(0,0);return}if(a==='back'){if(step===2)readDraft();step=Math.max(1,step-1);setup();return}
 if(a==='join-party'||a==='new-party'){readDraft();draft.custom=a==='new-party';setup();return}if(a==='launch'){launch();return}
 if(a==='profile-sources'){showModal('<h2>'+esc(getProfile().name)+' sources</h2>'+DATA.sources.filter(x=>getProfile().sources.includes(x.id)).map(sourceCard).join(''));return}
 if(a==='resume'){render();return}
 if(a==='new'){showModal('<h2>Start a new political career?</h2><p>Export your current save first if you want to return to it. Starting a new career replaces the local autosave only after you launch the new campaign.</p>'+button('Export current save','export','button')+' '+button('Set up a new career','confirm-new','button primary'));return}
 if(a==='confirm-new'){modal.close();state=null;step=1;country='AU';jurisdiction='AU';draft.party='';draft.home='';draft.custom=false;setup();return}
 if(a==='zoom-in'){mapZoom=Math.min(4,mapZoom*1.3);state?workspace():setup();return}if(a==='zoom-out'){mapZoom=Math.max(.6,mapZoom/1.3);state?workspace():setup();return}if(a==='map-reset'){mapZoom=1;mapFocus=null;state?workspace():setup();return}
 if(!state)return;
 if(a==='tab'){state.tab=id;districtSearch='';regionFilter='';mapZoom=1;mapFocus=null;save();workspace();window.scrollTo(0,0);return}
 const shortcuts={'policy-shortcut':'policies','map-shortcut':'map','parliament-shortcut':'parliament','sources-shortcut':'sources'};if(shortcuts[a]){state.tab=shortcuts[a];save();workspace();window.scrollTo(0,0);return}
 if(a==='map-seat'){const p=getProfile(),d=districtRows(p).find(x=>x.name===id);showModal('<div class="eyebrow">ELECTORAL LANDSCAPE</div><h2 style="margin-top:12px">'+esc(id)+'</h2><p>'+(d?'Region: '+esc(d.region||p.name)+'. ':'')+'Local standing, campaign targeting and simulated voting determine your gameplay prospects. The map shape itself is source geography.</p>'+button('Set campaign target','target','button primary',`data-id="${esc(id)}"`)+' '+button('Zoom to district','focus-seat','button',`data-id="${esc(id)}"`));return}
 if(a==='focus-seat'){mapFocus=id;mapZoom=1;modal.close();workspace();return}
 if(a==='target'){state.target=id;modal.close();save();workspace();toast('Campaign target set: '+id);return}
 if(a==='act'){if(!E.act(state,id))toast('This action is unavailable. Check your funds and remaining actions.');else toast(E.actions[id].name+' completed.');save();workspace();return}
 if(a==='advance'){E.advance(state,getProfile());save();workspace();window.scrollTo(0,0);return}
 if(a==='resolve'){if(E.resolve(state,Number(id))){save();workspace()}else toast('This response exceeds your available funds.');return}
 if(a==='coalition'){const success=E.coalition(state,Number(id));save();workspace();toast(success?'Confidence agreement secured.':'The party declined this simulated agreement.');return}
 if(a==='opposition'){E.opposition(state);save();workspace();return}
 if(a==='policy'){const success=state.phase==='government'?E.legislate(state,id):E.propose(state,id);save();workspace();toast(success?'Programme updated.':'The proposal did not pass or is unavailable.');return}
}
app.addEventListener('input',e=>{const el=e.target;if(el.id==='country-search'){countrySearch=el.value;document.getElementById('country-list').innerHTML=countryList()}
 if(el.id==='name'){draft.name=el.value;document.getElementById('preview-name').textContent=el.value||'Your politician';document.getElementById('preview-initials').textContent=initials(el.value||'Your politician')}
 if(el.id==='seat-search'){const p=getProfile(),needle=el.value.toLowerCase(),home=document.getElementById('home'),rows=p.districts.filter(d=>d.name.toLowerCase().includes(needle)||String(d.region).toLowerCase().includes(needle));home.innerHTML=rows.map(d=>`<option>${esc(d.name)}</option>`).join('');if(!rows.length&&p.districts.length)home.innerHTML='<option value="">No matching districts</option>'}
 if(el.id==='district-search'){districtSearch=el.value;updateTable()}
});
app.addEventListener('change',e=>{if(e.target.id==='jurisdiction'){jurisdiction=e.target.value;draft.party='';draft.home='';draft.custom=!getProfile().parties.length;mapZoom=1;mapFocus=null;setup()}if(e.target.id==='region-filter'){regionFilter=e.target.value;updateTable()}});
function updateTable(){const p=getProfile(),rows=districtRows(p).filter(d=>d.name.toLowerCase().includes(districtSearch.toLowerCase())&&(!regionFilter||d.region===regionFilter));const target=document.getElementById('district-table-body');if(target)target.innerHTML=tableBody(p,rows)}
document.getElementById('import').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>8*1024*1024)throw Error('Save exceeds 8 MB');const s=JSON.parse(await file.text());if(!E.validSave(s,DATA))throw Error('Not a valid Mandate 2026 career save');state=s;save();render();toast('Career imported.')}catch(err){toast(err.message)}e.target.value=''});
render();
// Deterministic test access; no account data or network requests are involved.
window.Mandate={getState:()=>state,getProfile,render,data:DATA,start:(p,c)=>{state=E.create(p,c);save();render()},reset:()=>{state=null;step=1;setup()}};
})();
